# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student

def check_students(students: List[Student]) -> None:
    """Refuse an empty list or a student with no email."""
    if not students:
        raise ValueError("no students given")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email address for {name}")

def by_name(student: Student) -> tuple:
    return (student.last_name, student.first_name)

def column_widths(students: List[Student]) -> tuple:
    """Widest name and section, for column alignment."""
    names = [len(item.display_name) for item in students]
    sections = [len(item.section) for item in students]
    return max(names), max(sections)

def contact_row(student: Student, widths: tuple) -> str:
    """Name, section and email padded into columns."""
    name_width, section_width = widths
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"

def contact_rows(students: List[Student]) -> List[str]:
    """One aligned text row per student, sorted by name."""
    check_students(students)
    ordered = sorted(students, key=by_name)
    widths = column_widths(ordered)
    return [contact_row(item, widths) for item in ordered]
